.fx-vlb .vid{position:relative;overflow:hidden;background:linear-gradient(115deg,color-mix(in srgb,var(--primary) 60%,#000),color-mix(in srgb,var(--primary) 78%,#000),color-mix(in srgb,var(--accent) 45%,color-mix(in srgb,var(--primary) 60%,#000)),color-mix(in srgb,var(--accent) 80%,#000),color-mix(in srgb,var(--primary) 60%,#000));background-size:300% 300%;animation:fxvidbg-vlb calc(14s/var(--speed)) ease-in-out infinite}
.fx-vlb .vid::before{content:"";position:absolute;width:55%;aspect-ratio:1;border-radius:50%;right:-10%;top:-30%;background:radial-gradient(circle,rgba(255,255,255,.35),transparent 65%);animation:fxvidfloat-vlb calc(9s/var(--speed)) ease-in-out infinite alternate}
.fx-vlb .vid::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(0,0,0,.35));pointer-events:none}
@keyframes fxvidbg-vlb{50%{background-position:100% 100%}}
@keyframes fxvidfloat-vlb{to{transform:translate(-40%,30%) scale(1.2)}}
@media(prefers-reduced-motion:reduce){.fx-vlb .vid,.fx-vlb .vid::before{animation:none}}
.fx-vlb{position:relative;width:min(920px,100%);height:600px;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 94%,var(--text))}.fx-vlb .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.7em 1.15em;border-radius:var(--radius);font:600 .92em var(--font-body);cursor:pointer;border:1px solid var(--border);background:transparent;color:var(--text);transition:background calc(.2s/var(--speed)),color calc(.2s/var(--speed)),transform calc(.2s/var(--speed)),border-color calc(.2s/var(--speed))}
.fx-vlb .btn:hover{border-color:var(--primary);color:var(--primary)}
.fx-vlb .btn.pri{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}
.fx-vlb .btn.pri:hover{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-vlb .btn.acc{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.fx-vlb .btn:active{transform:translateY(1px)}
.fx-vlb :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-vlb .scrim{position:absolute;inset:0;z-index:20;display:grid;place-items:center;padding:1em;background:color-mix(in srgb,#0b0e14 48%,transparent);backdrop-filter:blur(2px);visibility:hidden;opacity:0;transition:opacity calc(.25s/var(--speed)),visibility 0s linear calc(.25s/var(--speed))}
.fx-vlb .scrim.open{visibility:visible;opacity:1;transition-delay:0s}
.fx-vlb .pg{position:absolute;inset:0;padding:1.3em 1.5em;display:grid;gap:1em;align-content:start;overflow:hidden}
.fx-vlb .pg h2{font-size:clamp(1.4em,3.6vw,2em)}
.fx-vlb .th{position:relative;display:block;width:100%;border:0;padding:0;cursor:pointer;aspect-ratio:16/8;border-radius:var(--radius);overflow:hidden;color:#fff;text-align:left}
.fx-vlb .th .vid{position:absolute;inset:0;transition:transform calc(.6s/var(--speed)) cubic-bezier(.2,.8,.2,1)}.fx-vlb .th:hover .vid{transform:scale(1.04)}
.fx-vlb .th .pb{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:4.4em;height:4.4em;border-radius:50%;background:#fff;color:color-mix(in srgb,var(--primary) 65%,#000);display:grid;place-items:center;z-index:2;transition:transform calc(.3s/var(--speed)) cubic-bezier(.3,1.5,.5,1)}
.fx-vlb .th:hover .pb{transform:translate(-50%,-50%) scale(1.12)}.fx-vlb .th .pb svg{width:1.6em;height:1.6em;margin-left:.15em}
.fx-vlb .th .tx{position:absolute;left:1.1em;bottom:.9em;z-index:2;font:600 .95em var(--font-heading)}.fx-vlb .th .tx small{display:block;font:500 .78em var(--font-body);opacity:.85}
.fx-vlb .th:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-vlb .scrim{background:color-mix(in srgb,#05070b 82%,transparent);backdrop-filter:blur(4px)}
.fx-vlb .lb{position:relative;width:min(760px,100%);transform:scale(.94);transition:transform calc(.4s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-vlb .scrim.open .lb{transform:none}
.fx-vlb .x{position:absolute;right:0;top:-2.9em;display:inline-flex;align-items:center;gap:.5em;padding:.45em .8em;border-radius:99px;border:1px solid rgba(255,255,255,.35);background:transparent;color:#fff;font:600 .8em var(--font-body);cursor:pointer}
.fx-vlb .x:hover{background:rgba(255,255,255,.14)}
.fx-vlb .scr{position:relative;aspect-ratio:16/9;border-radius:var(--radius);overflow:hidden;box-shadow:0 30px 70px -20px rgba(0,0,0,.7)}
.fx-vlb .scr .vid{position:absolute;inset:0}
.fx-vlb .scr .tt{position:absolute;left:0;right:0;top:36%;text-align:center;color:#fff;z-index:2;font:600 clamp(1.1em,4vw,1.9em) var(--font-heading);text-shadow:0 2px 20px rgba(0,0,0,.35);pointer-events:none}
.fx-vlb .scr .tt small{display:block;font:500 .45em var(--font-body);letter-spacing:.2em;text-transform:uppercase;opacity:.85;margin-top:.7em}
.fx-vlb .ctl{position:absolute;left:0;right:0;bottom:0;z-index:3;display:flex;align-items:center;gap:.8em;padding:1.4em 1em .8em;color:#fff;background:linear-gradient(transparent,rgba(0,0,0,.6))}
.fx-vlb .ctl button{all:unset;cursor:pointer;width:2.2em;height:2.2em;display:grid;place-items:center;border-radius:50%;flex:none}.fx-vlb .ctl button:hover{background:rgba(255,255,255,.2)}.fx-vlb .ctl button:focus-visible{outline:2px solid #fff}
.fx-vlb .ctl svg{width:1.2em;height:1.2em}
.fx-vlb .ctl time{font:600 .75em var(--font-body);font-variant-numeric:tabular-nums;opacity:.9;white-space:nowrap}
.fx-vlb .ctl input{flex:1;min-width:0;appearance:none;-webkit-appearance:none;height:.3em;border-radius:99px;cursor:pointer;background:linear-gradient(90deg,var(--accent) var(--p,0%),rgba(255,255,255,.35) 0)}
.fx-vlb .ctl input::-webkit-slider-thumb{-webkit-appearance:none;width:.9em;height:.9em;border-radius:50%;background:#fff;border:0;box-shadow:0 1px 6px rgba(0,0,0,.4)}
.fx-vlb .ctl input::-moz-range-thumb{width:.9em;height:.9em;border-radius:50%;background:#fff;border:0}
.fx-vlb .ctl input:focus-visible{outline:2px solid #fff;outline-offset:4px}
.fx-vlb .scr.paused .vid,.fx-vlb .scr.paused .vid::before{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){.fx-vlb .lb,.fx-vlb .th .vid,.fx-vlb .th .pb{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-vlb .btn.is-tap{border-color:var(--primary);color:var(--primary)}
.fx-vlb .btn.pri.is-tap{background:color-mix(in srgb,var(--primary) 85%,var(--text));color:var(--on-primary)}
.fx-vlb .th.is-tap .vid{transform:scale(1.04)}
.fx-vlb .th.is-tap .pb{transform:translate(-50%,-50%) scale(1.12)}
.fx-vlb .x.is-tap{background:rgba(255,255,255,.14)}
.fx-vlb .ctl button.is-tap{background:rgba(255,255,255,.2)}

