(function(){var root=document.querySelector('.fx-vlb'),pg=root.querySelector('.pg'),sc=root.querySelector('.scrim'),lb=root.querySelector('.lb'),scr=root.querySelector('.scr'),pp=root.querySelector('[data-pp]'),rg=root.querySelector('input'),cur=root.querySelector('.cur'),op=null,t=0,T=134,iv=null,playing=false;
function focusables(c){return [].slice.call(c.querySelectorAll('button,input,select,textarea,a[href],[tabindex]:not([tabindex="-1"])')).filter(function(e){return !e.disabled&&e.offsetParent!==null})}
function trap(e,c){if(e.key!=='Tab')return;var f=focusables(c);if(!f.length)return;var a=f[0],z=f[f.length-1];
if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}

var PL='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.86l11-6.5a1 1 0 0 0 0-1.72l-11-6.5A1 1 0 0 0 8 5.5z" fill="currentColor"/></svg>',PA='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="5" width="4" height="14" rx="1" fill="currentColor"/><rect x="14" y="5" width="4" height="14" rx="1" fill="currentColor"/></svg>';
function fmt(s){s=Math.floor(s);return Math.floor(s/60)+':'+('0'+s%60).slice(-2)}
function paint(){rg.value=t;rg.style.setProperty('--p',t/T*100+'%');cur.textContent=fmt(t)}
function play(on){playing=on;scr.classList.toggle('paused',!on);pp.innerHTML=on?PA:PL;pp.setAttribute('aria-label',on?'Pause':'Play');clearInterval(iv);if(on)iv=setInterval(function(){t+=.25;if(t>=T){t=T;paint();play(false)}else paint()},250)}
function open(b){op=b;t=0;paint();sc.classList.add('open');sc.setAttribute('aria-hidden','false');pg.inert=true;play(true);requestAnimationFrame(function(){pp.focus()})}
function close(){if(!sc.classList.contains('open'))return;play(false);sc.classList.remove('open');sc.setAttribute('aria-hidden','true');pg.inert=false;if(op)op.focus()}
root.querySelector('[data-open]').addEventListener('click',function(e){open(e.currentTarget)});root.querySelector('[data-close]').addEventListener('click',close);
sc.addEventListener('mousedown',function(e){if(e.target===sc)close()});pp.addEventListener('click',function(){if(!playing&&t>=T)t=0;play(!playing)});
scr.querySelector('.vid').addEventListener('click',function(){pp.click()});rg.addEventListener('input',function(){t=+rg.value;paint()});
document.addEventListener('keydown',function(e){if(!sc.classList.contains('open'))return;if(e.key==='Escape')close();else trap(e,lb)});})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
